questionvariables.text:
/* Standard angles beyond the first quadrant, excluding the quadrantal angles 180 and 270 and 360 (no reference angle, tan 270 undefined) */
angledeg: rand([120,135,150,210,225,240,300,315,330]);
fn: rand(3);   /* 0 sin, 1 cos, 2 tan */
/* exact value computed by Maxima from the angle in radians (checked for every angle and function) */
ta: if fn = 0 then sin(angledeg*%pi/180) elseif fn = 1 then cos(angledeg*%pi/180) else tan(angledeg*%pi/180);
quadrant: if angledeg < 180 then 2 elseif angledeg < 270 then 3 else 4;
refangle: if quadrant = 2 then 180 - angledeg elseif quadrant = 3 then angledeg - 180 else 360 - angledeg;
/* Diagnostic: right magnitude, wrong sign for the quadrant. ta is never 0, so this is always distinct. */
wrong_sign: -ta;
